func TestRestoreLogsOnly_OverwritesWhenCheckpointNewer(t *testing.T) {
	dir := t.TempDir()
	testutil.InitRepo(t, dir)
	t.Chdir(dir)

	repo, err := git.PlainOpen(dir)
